 for(const m of (s.rails||[]).filter(r=>s.buildings.some(b=>b.id===r.from)&&s.buildings.some(b=>b.id===r.to))){c.strokeStyle='#657c76';c.lineWidth=2;c.setLineDash([3,4]);c.beginPath();for(let i=0;i<m.route.length;i++){const p=this.screen(point(m.route[i]));i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y)}c.stroke();c.setLineDash([])}
 if(options.selected!==null&&options.selected!==undefined){const p=this.screen(point(options.selected));c.strokeStyle='#fff0b2';c.lineWidth=1.5;c.strokeRect(p.x-scale/2-2,p.y-scale/2-2,scale+4,scale+4);const b=s.buildings.find(b=>b.cell===options.selected);if(b&&['fort','shield'].includes(b.kind)){c.strokeStyle=b.kind==='shield'?'#aff4d59a':'#e9d4a666';c.fillStyle=b.kind==='shield'?'#8be9c813':'#d3b98212';const r=(b.kind==='shield'?10+b.level*5:7+b.level*2)*scale;c.beginPath();c.arc(p.x,p.y,r,0,Math.PI*2);c.fill();c.stroke()}}
 for(const city of s.map.cities){const p=this.screen(point(city.cell));if(p.x<-100||p.y<-30||p.x>w+100||p.y>h+30)continue;c.fillStyle='#f5e4c6';c.fillRect(p.x-2,p.y-2,4,4);if(scale>this.fitScale*.75){c.font=`${Math.min(11,9+scale/10)}px PixelLocal,monospace`;c.textAlign='center';c.lineWidth=3;c.strokeStyle='#152b39bb';c.strokeText(city.name,p.x,p.y+13);c.fillStyle='#d4e6d8';c.fillText(city.name,p.x,p.y+13)}}
